\begin{tikzpicture}[font=\sffamily, >=Stealth, x=1cm, y=1cm]
  \fill[black!8] (0,0) rectangle (6,3.2);
  \draw[thick] (0,4) -- (0,0) -- (6,0) -- (6,4);
  \draw (0,3.2) -- (6,3.2);
  % bag
  \draw[thick, fill=black!25] (3,1.4) ellipse (1.3 and 1.0);
  % capillary tube
  \draw[fill=white] (2.9,2.3) rectangle (3.1,5.1);
  \fill[black!25] (2.9,2.3) rectangle (3.1,3.8);
  \draw (2.9,2.3) rectangle (3.1,5.1);
  \draw (2.88,3.8) -- (3.12,3.8);
  % labels
  \draw (3.1,4.7) -- (4.2,4.7) node[right] {capillary tube};
  \draw (0.2,2.6) -- (-0.8,2.6) node[left] {distilled water};
  \draw (2.2,0.9) -- (1.5,0.9) -- (1.0,-0.6) node[below] {concentrated sucrose solution};
  \draw (4.25,1.7) -- (6.8,1.7) node[right] {Visking tubing bag};
  \node at (3,-1.8) {Fig. 2.1};
\end{tikzpicture}
